// Detect email source from various indicators
function detectSource(item) {
  const text = item.json.textPlain || '';
  const from = item.json.from || '';
  const subject = item.json.subject || '';

  // LinkedIn detection
  if (text.includes('View job:') && (from.includes('linkedin') || subject.includes('LinkedIn'))) {
    return 'linkedin';
  }

  // Indeed detection
  if (from.includes('indeed') || text.includes('Indeed') || text.includes('Apply now')) {
    return 'indeed';
  }

  // Default to unknown
  return 'unknown';
}

// LinkedIn parser (your existing logic with improvements)
function parseLinkedIn(text, emailDate) {
  const blocks = text
    .split(/\s*-{20,}\s*/)
    .map(b => b.trim())
    .filter(b => b.length > 0 && b.includes('View job:'));

  return blocks.map(block => {
    const lines = block.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

    const urlLineIdx = lines.findIndex(l => l.startsWith('View job:'));
    let jobUrl = null;
    if (urlLineIdx !== -1) {
      jobUrl = lines[urlLineIdx].replace('View job:', '').trim();
      if (!jobUrl && urlLineIdx + 1 < lines.length) {
        jobUrl = lines[urlLineIdx + 1];
      }
    }

    const jobIdMatch = jobUrl ? jobUrl.match(/jobs\/view\/(\d+)\//) : null;
    const jobId = jobIdMatch ? jobIdMatch[1] : null;
    const canonicalUrl = jobId ? `https://www.linkedin.com/jobs/view/${jobId}/` : null;

    // Extract job details from lines before "View job:"
    const contentLines = urlLineIdx > -1 
      ? lines.slice(0, urlLineIdx)
      : lines;

    const skipPatterns = /^(your job alert|results from|this company|view job|subject:|date:|from:|to:|---|http|\d)/i;
    const filteredLines = contentLines.filter(l => !skipPatterns.test(l));

    return {
      job_id: jobId,
      job_title: filteredLines[filteredLines.length - 3] || null,
      company: filteredLines[filteredLines.length - 2] || null,
      location: filteredLines[filteredLines.length - 1] || null,
      job_url: canonicalUrl,
      received_at: emailDate,
      source: 'linkedin',
      digested: false
    };
  }).filter(job => job.job_id !== null);
}

// Indeed parser
function parseIndeed(text, emailDate) {
  const jobs = [];

  // Split by job separators (Indeed uses horizontal rules or "Apply now" sections)
  const blocks = text.split(/\s*-{20,}|\s*Apply now\s*/i);

  for (const block of blocks) {
    if (!block.trim() || block.length < 50) continue;

    const lines = block.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

    // Find job URL (Indeed format: indeed.com/viewjob?jk=JOB_ID)
    const urlLine = lines.find(l => l.includes('indeed.com/viewjob') || l.includes('indeed.com/viewjob'));
    let jobUrl = urlLine ? urlLine : null;

    // Extract job ID from URL
    let jobId = null;
    if (jobUrl) {
      const match = jobUrl.match(/viewjob\?jk=([a-zA-Z0-9]+)/);
      jobId = match ? match[1] : null;
      canonicalUrl = `https://www.indeed.com/viewjob?jk=${jobId}`;
    }

    // Extract job title (usually first non-empty meaningful line)
    const titleLine = lines.find(l => {
      if (l.length < 10 || l.length > 100) return false;
      if (l.includes('Apply') || l.includes('indeed') || l.includes('http')) return false;
      if (l.includes('$') || l.match(/^\d/)) return false; // Skip salary/numbers
      return true;
    });

    // Extract company (often contains "at" or follows title)
    const companyLine = lines.find(l => {
      if (l.includes('at ') || l.includes(' in ')) return true;
      if (l.length > 5 && l.length < 50 && !l.includes('$')) return true;
      return false;
    });

    // Extract location (contains city, state, or "Remote")
    const locationLine = lines.find(l => {
      if (l.includes('Remote') || l.includes('remote')) return true;
      if (l.match(/[A-Z][a-z]+,\s*[A-Z]{2}/)) return true; // City, State pattern
      return false;
    });

    if (jobId) {
      jobs.push({
        job_id: jobId,
        job_title: titleLine || null,
        company: companyLine || null,
        location: locationLine || null,
        job_url: canonicalUrl,
        received_at: emailDate,
        source: 'indeed'
      });
    }
  }

  return jobs;
}

// Main processing
const rawText = $input.item.json.textPlain || '';
const emailDate = $input.item.json.date || new Date().toISOString();
const source = detectSource($input.item);

let jobs = [];

if (source === 'linkedin') {
  jobs = parseLinkedIn(rawText, emailDate);
} else if (source === 'indeed') {
  jobs = parseIndeed(rawText, emailDate);
} else {
  // Try both parsers as fallback
  jobs = [...parseLinkedIn(rawText, emailDate), ...parseIndeed(rawText, emailDate)];
  // Remove duplicates
  jobs = jobs.filter((job, index, self) => 
    index === self.findIndex(t => t.job_id === job.job_id && t.source === job.source)
  );
}

// Return in n8n format
return jobs.map(job => ({ json: job }));
